// MOVE 3 (move3-1 .. move3-9), Rokossovsky #8: Operation Bagration / Bobruisk, June 1944. Basemap bobruisk_hd_ref (Belarus z9, HD).
// move3-1 wide (option 1, 22 June control): the German bulge, Busch, the panzers sent south to Ukraine, forests / rivers / marshes.
// move3-2 .. move3-7 close-up (option 2: two-colour glowing front lines only): one blow vs two blows; the Stalin card (text only, no
//   likeness); log roads + swamp-shoes + rafts; 24 June barrage, the north stalls, the south breaks through the marsh, Soviet bombers;
//   25-27 June the ring closes (TRAPPED); the pocket is bombed and smashed; Busch sacked 28 June; Bobruisk freed 29 June, Marshal.
// move3-8 wide again (option 1): four fronts, Minsk 3 July, control 22 Jun -> 4 Jul -> end of summer, ~400,000 (WHOLE operation).
// move3-9 casualty card (FACT_NOTES numbers) + the method card. Fronts per date: research/FACT_NOTES_bobruisk.md.
const B = Battle();
const { at, P: PS } = B;
const END = B.T.duration;
const K = FXK(B);
const GG = GGK(B);
const PR = GG.proj(9, 74836, 41886);
const L = (lat, lon) => PR(lat, lon);
const USSR = "assets/media/ussr_flag.png", REICH = "assets/media/ger_reich_flag.png";
const PHOTO = { roko: null, busch: null }; // TODO: assets/media/rokossovsky_head.png / busch_head.png when the photo agent delivers them
// ---------- helpers (same as hook-a.js) ----------
const box = (txt, x, y, t, size = 16, until) => { SFX("ref:pop", t); return GG.pin(`<div style="background:#f1eee6;color:#111;font-family:Oswald;font-weight:500;letter-spacing:.28em;padding:${Math.round(size * 0.2)}px ${Math.round(size * 0.35)}px ${Math.round(size * 0.2)}px ${Math.round(size * 0.6)}px;font-size:${size}px;white-space:nowrap;box-shadow:0 2px 8px rgba(0,0,0,.6)">${txt}</div>`, x, y, { t, until }); };
const town = (txt, lat, lon, t, o = {}) => { const [x, y] = L(lat, lon); B.city("", x, y, { r: o.r || 5, t, until: o.until }); return box(txt, x + (o.dx || 0), y + (o.dy != null ? o.dy : -22), t, o.size || 13, o.until); };
const flag = (src, name, x, y, t, until, w = 76) => GG.pin(`<div style="display:flex;flex-direction:column;align-items:center;gap:4px"><img src="${src}" style="width:${w}px;display:block;border:2px solid #1a1712;box-shadow:0 3px 8px rgba(0,0,0,0.55)"><div class="gg-lbl" style="position:relative;font-size:${Math.round(w / 4)}px;color:#f7f3ea;text-shadow:0 2px 4px #000;letter-spacing:0.08em">${name}</div></div>`, x, y, { t, pop: true, until });
const unit = (id, side, lat, lon, icon, label, o = {}) => {
  const [x, y] = L(lat, lon), w = o.w || 30, h = o.h || 20;
  B.unit({ id, side, x, y, w, h, t: o.t, label });
  K.counter(id, { icon, flag: side === "rome" ? "ger" : "us", size: o.size });
  if (side === "carth") B.units[id].el.querySelector(".fxk-flag").src = USSR;   // lib/fx.js FLAGS has no USSR key: set the chip here
  if (o.until != null) B.hideUnits([id], o.until);
  return id;
};
const go = (id, t, dur, lat, lon, ease) => { const [x, y] = L(lat, lon); B.move(id, t, dur, x, y, ease || "power1.inOut"); };
const LL = (pts) => pts.map(([la, lo]) => L(la, lo));
const logRoad = (pts, t, dur = 2.2, until) => {   // corduroy log road: brown ties on a dark bed, revealed along the path
  const NS = "http://www.w3.org/2000/svg", svg = document.getElementById("overlay"), g = document.createElementNS(NS, "g");
  const d = "M" + pts.map((q) => q[0].toFixed(1) + " " + q[1].toFixed(1)).join(" L");
  const id = "lr" + Math.round(pts[0][0] * 7 + pts[0][1] * 3 + t * 10);
  g.innerHTML = `<mask id="${id}" maskUnits="userSpaceOnUse" x="0" y="0" width="2880" height="1620"><path d="${d}" fill="none" stroke="#fff" stroke-width="14" stroke-linecap="round"/></mask>
    <g mask="url(#${id})"><path d="${d}" fill="none" stroke="rgba(30,20,10,0.7)" stroke-width="8" stroke-linecap="round"/><path d="${d}" fill="none" stroke="#b08a56" stroke-width="6" stroke-dasharray="1.6 2.4"/></g>`;
  svg.appendChild(g);
  const mp = g.querySelector("mask path"), len = mp.getTotalLength();
  gsap.set(mp, { strokeDasharray: `${len} ${len}`, strokeDashoffset: len });
  B.tl.to(mp, { strokeDashoffset: 0, duration: dur, ease: "power1.inOut" }, t);
  if (until != null) B.tl.to(g, { opacity: 0, duration: 0.6 }, until);
  return g;
};
const legend = (t, until, opt2) => GG.card(`<div style="display:flex;gap:26px;font-size:20px;letter-spacing:0.1em;align-items:center">${[["#2e5cb2", "#2c57b7", "SOVIET"], ["#be3a2a", "#bc2528", "GERMAN"]].map(([sq, ln, nm]) => `<span><b style="display:inline-block;width:20px;height:${opt2 ? 6 : 20}px;background:${opt2 ? ln : sq};${opt2 ? `box-shadow:0 0 8px ${ln};vertical-align:4px;` : "vertical-align:-3px;"}margin-right:8px;border:1px solid #f7f3ea"></b>${nm}</span>`).join("")}</div>`, "", 34, t, until);
const ctl = (state, t, dur, until) => { const el = B.image(`assets/media/bobruisk_ctl_${state}_mx.png`, 0, 0, 2880, 1620, { t, dur, until }); el.style.mixBlendMode = "multiply"; return el; };
const img0 = (src, until, mx) => {
  const el = document.createElement("img"); el.className = "wimg"; el.src = src; el.alt = "";
  Object.assign(el.style, { left: "0px", top: "0px", width: "2880px", height: "1620px" }); if (mx) el.style.mixBlendMode = "multiply";
  document.getElementById("world").insertBefore(el, document.getElementById("overlay"));
  if (until != null) B.tl.to(el, { autoAlpha: 0, duration: 1.0 }, until);
  return el;
};
const posOn = (pts, f) => {   // point at fraction f of a polyline's length
  let Lt = 0; const seg = []; for (let j = 1; j < pts.length; j++) { const d = Math.hypot(pts[j][0] - pts[j - 1][0], pts[j][1] - pts[j - 1][1]); seg.push(d); Lt += d; }
  let d = f * Lt; for (let j = 0; j < seg.length; j++) { if (d <= seg[j]) { const a = pts[j], b = pts[j + 1], k = d / seg[j]; return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k]; } d -= seg[j]; }
  return pts[pts.length - 1];
};
// Soviet bombers: the locked K.bombRun with the glowing C-47 symbol in blue; bombs land on the plane's track (0.25 s apart, shake on the first)
const bomber = (pts, t, n = 4, dur = 4.2, size = 40) => {
  const bombs = []; for (let k = 0; k < n; k++) bombs.push(posOn(pts, (1.55 + k * 0.25) / dur).map((v, i) => v + (i ? (k % 2 ? 6 : -6) : 0)));
  K.bombRun({ kind: "c47g", side: "carth", size, alt: 12, dur, pts, t, bombs });
};
